def left_rotate(n, d):
    if d == 0:
        return n
    # Handle rotation count larger than 32 by taking modulo 32
    d = d % 32
    # Perform the rotation: (n << d) | (n >> (32 - d))
    return (n << d) | (n >> (32 - d))
```

